import pandas as pd

def solve(data):
     codes = pd.Series(data['codes'], dtype='string')
     qty = pd.to_numeric(pd.Series(data['qty']), errors='coerce').astype('Int64')
     return {'codes': codes.tolist(), 'qty': [None if pd.isna(v) else int(v) for v in qty], 'dtype': str(qty.dtype)}
